function landing() {
 return `<div class="landing"><nav class="landing-nav" aria-label="Prototype">${brand}<span class="wordmark">helpdesk<span style="color:var(--accent)">.</span></span><span class="top-divider"></span><span class="small muted">Independent design study</span><span class="spacer"></span><span class="demo-label">Interactive concept · synthetic data</span>${themeButton()}</nav><main class="landing-main" id="main"><div class="landing-hero"><div><div class="concept-label">Graphite / a new perspective</div><h1>Considered in every detail.<br>Built around the work.</h1><p>A quieter, sharper Helpdesk. Four connected workspaces exploring a more confident identity for the people who keep an organisation running.</p></div><div class="landing-actions"><a class="btn primary" href="workspace.html">Explore the workspace ${icon('arrow-right')}</a><small>Light & dark · desktop & laptop</small></div></div><div class="preview-grid">${screens.map(([id,label,desc],i)=>`<a class="screen-preview" href="${id}.html"><div class="screen-frame"><img src="screenshots/${id}-${theme}-1440x900.png" alt="${label}, ${theme} theme" width="1440" height="900"></div><div class="screen-caption"><span class="screen-number">0${i+1}</span><div><h2>${label}</h2><p>${desc}</p></div>${icon('arrow-up-right')}</div></a>`).join('')}</div><footer class="landing-footer"><span>A visual proposal, separate from the live application. Nothing here sends email or changes real data.</span><div class="review-links"><a href="README.md">Design notes</a><a href="gallery.html">All screenshots</a></div></footer></main></div>`;
}
