function showPreview(title) {
 if(title==='Manage acknowledgements') title='Acknowledgements';
 if(title==='Requester history') { const t=currentTicket();dialog(title,`<p class="preview-caption">Sample history scoped to IT Services for ${esc(t.requester)}.</p><ul class="preview-list"><li>${icon('ticket')}<div><strong>${t.id}</strong><small>${esc(t.subject)} · ${esc(t.status)}</small></div></li></ul>`);return; }
 const rows=examples[title] || [[title,'A visual navigation preview. This configuration area is outside the four completed screens.']];
 dialog(title,`<p class="preview-caption">Illustrative configuration. No live data is read or changed.</p><ul class="preview-list">${rows.map(([a,b])=>`<li>${icon('chevron-right')}<div><strong>${esc(a)}</strong><small>${esc(b)}</small></div></li>`).join('')}</ul>`);
}
let editingMailbox=null;
function openMailbox(id) {
 editingMailbox=id?mailboxes.find(m=>m.id===Number(id)):null;
 const m=editingMailbox;
 $('#mailbox-drawer').innerHTML=`<form id="mailbox-form"><div class="dialog-header"><div><span class="small muted">IT Services / Mailboxes</span><h2 id="mailbox-title" style="margin-top:9px">${m?'Edit mailbox':'Add mailbox'}</h2><p>${m?'Manage the sender identity and availability.':'Connect a shared identity for your Department.'}</p></div><button type="button" class="icon-btn" data-action="close-dialog" aria-label="Close mailbox drawer">${icon('x')}</button></div><div class="dialog-body"><div class="info-block" style="margin-bottom:24px"><span class="microsoft-mark" aria-hidden="true"><i></i><i></i><i></i><i></i></span><div><strong class="small">Microsoft Graph</strong><p>${m?'Existing Exchange Online shared mailbox.':'The shared mailbox must already exist in Microsoft 365.'}</p></div></div><label class="field"><span>Mailbox address</span><input id="mailbox-address" aria-label="Mailbox address" name="address" type="email" maxlength="320" required value="${m?esc(m.address):''}" ${m?'readonly':''} placeholder="support@northstar.example" aria-describedby="address-hint"><small id="address-hint">${m?'The address is fixed for this mailbox.':'The shared mailbox that receives this Department’s email.'}</small></label><label class="field"><span>Sender name</span><input id="mailbox-name" aria-label="Sender name" name="name" maxlength="200" required value="${m?esc(m.name):''}" placeholder="IT Service Desk" aria-describedby="sender-hint" ${m?'autofocus':''}><small id="sender-hint">Shown as the sender of public replies.</small></label>${m?`<label class="field"><span>Mailbox availability</span><select name="state" id="mailbox-state"><option ${m.state==='Active'?'selected':''}>Active</option><option ${m.state==='Inactive'?'selected':''}>Inactive</option></select></label><div id="inactive-warning" class="notice error" ${m.state==='Inactive'?'':'hidden'}><div><strong>Public replies will be blocked</strong><p>Tickets using this mailbox cannot send email while it is inactive. Their sender will not switch.${m.default?' It is also the default for new tickets.':''}</p></div></div>`:''}<label class="checkbox-field"><input name="default" type="checkbox" ${m?.default?'checked':''}><span><strong>Default for new tickets</strong><small>Used when a new ticket needs a Department mailbox. Existing tickets keep their stored mailbox.</small></span></label><div class="sender-preview"><small>PUBLIC REPLY IDENTITY</small><div class="cell-main"><span class="dept-icon it">${icon('mail')}</span><div><strong id="sender-preview-name">${m?esc(m.name):'Sender name'}</strong><small id="sender-preview-address">${m?esc(m.address):'mailbox@northstar.example'}</small></div></div><p class="muted">From and Reply-To use this mailbox.</p></div><p class="form-error" id="mailbox-error" role="alert" hidden></p><p class="small muted">Prototype only. Saving updates this page’s sample data. No connection is made to Microsoft 365.</p></div><div class="dialog-footer"><span class="small muted" style="margin-right:auto">Local demonstration</span>${btn('Cancel','close-dialog')}<button type="submit" class="btn primary">${m?'Save changes':'Add mailbox'}</button></div></form>`;
 $('#mailbox-drawer').showModal();
 if(!m) $('#mailbox-address').focus();
 $('#mailbox-form').addEventListener('submit',saveMailbox);
 ['mailbox-address','mailbox-name'].forEach(id=>$('#'+id).addEventListener('input',()=>{ $('#sender-preview-name').textContent=$('#mailbox-name').value||'Sender name';$('#sender-preview-address').textContent=$('#mailbox-address').value||'mailbox@northstar.example'; }));
 if(m) $('#mailbox-state').addEventListener('change',()=>{ $('#inactive-warning').hidden=$('#mailbox-state').value==='Active'; });
}
function saveMailbox(e) {
 e.preventDefault();const form=e.currentTarget, data=new FormData(form);const address=String(data.get('address')).trim(),name=String(data.get('name')).trim(),state=String(data.get('state')||'Active'),isDefault=data.get('default')==='on';
 const fail=text=>{ $('#mailbox-error').textContent=text;$('#mailbox-error').hidden=false; };
 if(!name) { fail('Enter a sender name.');$('#mailbox-name').focus();return; }
 if(!address) { fail('Enter the shared mailbox address.');$('#mailbox-address').focus();return; }
 if(mailboxes.some(m=>m.address.toLowerCase()===address.toLowerCase() && m.id!==editingMailbox?.id)){fail('This mailbox is already configured in this example Department.');$('#mailbox-address').focus();return;}
 if(state==='Inactive' && isDefault && !editingMailbox?.default){fail('Choose an active mailbox as the new default.');return;}
 if(isDefault)mailboxes.forEach(m=>m.default=false);
 if(editingMailbox) { const previous=editingMailbox.state;Object.assign(editingMailbox,{name,state,default:isDefault});if(state==='Inactive')Object.assign(editingMailbox,{health:'Inactive',tone:'',subscription:'Not active'});else if(previous==='Inactive')Object.assign(editingMailbox,{health:'Not verified',tone:'amber',subscription:'Not connected'}); }
 else mailboxes.push({id:Date.now(),name,address,default:isDefault,state:'Active',health:'Not verified',tone:'amber',subscription:'Not connected',sync:'Never'});
 $('#mailbox-rows').innerHTML=mailboxRows();$('#mailbox-count').textContent=mailboxes.length;const expired=mailboxes.filter(m=>m.subscription==='Expired').length;$('#subscription-summary').innerHTML=badge(expired?`${expired} subscription${expired===1?'':'s'} need${expired===1?'s':''} attention`:'No expired subscriptions',expired?'amber':'green',expired?'alert-triangle':'check');const navCount=$('.side-link.active .nav-count');if(navCount)navCount.textContent=expired||'';$('#mailbox-drawer').close();toast(editingMailbox?'Sample mailbox updated. No real settings changed.':'Sample mailbox added. Microsoft Graph is not connected.');
}
function updateTicketList(){ $('.queue-nav').outerHTML=queueSidebar();$('#ticket-rows').innerHTML=ticketRows();$('#queue-count').textContent=visibleTickets().length; }
function saveDraft(){const input=$('#message-draft');if(input)drafts.set(selectedId+(noteMode?':note':':reply'),input.value);}
function renderTicket(){const t=currentTicket();$('#ticket-detail').innerHTML=detailMarkup(t);$('#properties').innerHTML=propertiesMarkup(t);bindComposer();updateTicketList();}
function bindComposer(){const form=$('#composer');if(!form)return;form.addEventListener('submit',e=>{e.preventDefault();const t=currentTicket(),body=$('#message-draft').value.trim();if(!body){$('#message-draft').setCustomValidity('Write a message before adding it.');$('#message-draft').reportValidity();return;}const messages=addedMessages.get(t.id)||[];messages.push({kind:noteMode?'note':'reply',body});addedMessages.set(t.id,messages);t.status=$('#after-send').value;drafts.delete(t.id+(noteMode?':note':':reply'));renderTicket();$('#conversation').scrollTop=$('#conversation').scrollHeight;toast(noteMode?'Demo Internal Note added locally.':'Demo reply added locally. No email was sent.');});$('#message-draft').addEventListener('input',e=>{e.target.setCustomValidity('');saveDraft();});}
function searchResults(query=''){const found=screens.filter(([,label])=>label.toLowerCase().includes(query.toLowerCase()));$('#command-results').innerHTML=found.map(([id,label])=>`<a class="command-result" href="${id}.html">${icon(id==='workspace'?'ticket':id==='mailboxes'?'mail':'settings')}<span>${label}</span><span class="spacer"></span>${icon('arrow-right')}</a>`).join('')||`<p class="empty-state">No matching screens.</p>`;}
function openSearch(){searchResults();$('#search-dialog').showModal();$('#command-search').focus();}
document.addEventListener('click',e=>{
 const target=e.target.closest('[data-action]');if(!target)return;const action=target.dataset.action;
 if(action.startsWith('preview:')){showPreview(action.slice(8));return;}
 if(action==='close-dialog'){target.closest('dialog')?.close();return;}
 if(action==='theme'){theme=theme==='light'?'dark':'light';document.documentElement.dataset.theme=theme;try{localStorage.setItem('graphite-theme',theme);}catch{}$$('[data-action="theme"]').forEach(b=>{b.innerHTML=icon(theme==='light'?'moon':'sun');b.setAttribute('aria-label',`Switch to ${theme==='light'?'dark':'light'} theme`);});$$('.screen-frame img').forEach(img=>{img.src=img.src.replace(/-(light|dark)-/,`-${theme}-`);img.alt=img.alt.replace(/light|dark/,theme);});return;}
 if(action==='search'){openSearch();return;}
 if(action==='add-mailbox'){openMailbox();return;}
 if(action.startsWith('edit-mailbox:')){openMailbox(action.split(':')[1]);return;}
 if(action==='mailbox-tab'){$('#main').scrollTo({top:0,behavior:'smooth'});return;}
 if(action==='attention-tab'){$('#mail-attention').scrollIntoView({behavior:'smooth',block:'center'});$('#mail-attention').focus({preventScroll:true});return;}
 if(action.startsWith('attention:')){const uncertain=action.endsWith('uncertain');dialog(uncertain?'Send outcome uncertain':'Delivery failed',`<div class="notice ${uncertain?'':'error'}">${icon(uncertain?'alert-triangle':'circle-x')}<div><strong>${uncertain?'Check before sending again':'The message was not delivered'}</strong><p>${uncertain?'The connection ended before a send outcome was confirmed. Retrying could send a duplicate email.':'The mail service reported a delivery failure for this reply.'}</p></div></div><div style="margin-top:22px"><h3>${uncertain?'IT-2046 · VPN access for the Edinburgh office':'IT-2031 · Replacement docking station'}</h3><p class="muted" style="margin-top:10px;font-size:13px">${uncertain?'Review the stored mailbox’s Sent Items and reconcile the send with the mail service before deciding whether to resend.':'Review the failure and the requester’s contact details before deciding whether a retry is appropriate. An email change does not change requester ownership.'}</p><p class="preview-caption" style="margin-top:20px">This prototype cannot check Microsoft Graph or retry a message.</p></div>`);return;}
 if(action==='clear-department-filters'){$('#department-search').value='';$('#department-status').value='all';filterDepartments();return;}
 if(action==='department-tab'){$('#department-search').focus();return;}
 if(action.startsWith('ticket:')){saveDraft();selectedId=action.split(':')[1];renderTicket();return;}
 if(action.startsWith('queue:')){saveDraft();queue=action.split(':')[1];$('.queue-nav').outerHTML=queueSidebar();$('#queue-title').textContent={my:'My queue',team:'Team queue',unassigned:'Unassigned',all:'All tickets',following:'Following',high:'High priority',pending:'Awaiting requester'}[queue];if(visibleTickets().length&&!visibleTickets().some(t=>t.id===selectedId)){selectedId=visibleTickets()[0].id;renderTicket();}updateTicketList();return;}
 if(action==='clear-ticket-search'){ticketFilter='';$('#ticket-search').value='';updateTicketList();return;}
 if(action==='sort'){sortNewest=!sortNewest;target.innerHTML=(sortNewest?'Newest first':'Oldest first')+icon('chevron-down');updateTicketList();return;}
 if(action==='note-mode'||action==='reply-mode'){saveDraft();noteMode=action==='note-mode';$('#composer').outerHTML=composerMarkup(currentTicket());bindComposer();$('#message-draft').focus();return;}
 if(action==='resolve'){saveDraft();const t=currentTicket();t.status=t.status==='Resolved'?'Open':'Resolved';renderTicket();toast(`Sample ticket ${t.status.toLowerCase()} locally.`);return;}
 if(action==='follow'){saveDraft();const t=currentTicket();t.following=!t.following;renderTicket();toast(t.following?'Following this sample ticket.':'Unfollowed this sample ticket.');return;}
 if(action==='conversation-tab'){$('#conversation').focus();return;}
});
document.addEventListener('change',e=>{if(e.target.matches('[data-property]')){saveDraft();const property=e.target.dataset.property;currentTicket()[property]=e.target.value;renderTicket();$('#'+property).focus();toast('Sample ticket updated locally.');}});
document.addEventListener('keydown',e=>{if(e.target.matches('.composer-tabs [role=tab]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?'reply-mode':e.key==='End'?'note-mode':noteMode?'reply-mode':'note-mode';document.querySelector(`[data-action="${next}"]`).click();document.querySelector(`[data-action="${next}"]`).focus();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!$('dialog[open]'))openSearch();}});
$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('#command-search').addEventListener('input',e=>searchResults(e.target.value));
function filterDepartments(){const rows=departmentRows($('#department-search').value,$('#department-status').value);$('#department-rows').innerHTML=rows;const count=$$('#department-rows tr').filter(r=>!r.querySelector('.empty-state')).length;$('#department-count').textContent=`Showing ${count} Department${count===1?'':'s'}`;}
if(page==='administration'){$('#department-search').addEventListener('input',filterDepartments);$('#department-status').addEventListener('change',filterDepartments);}
if(page==='workspace'){$('#ticket-search').addEventListener('input',e=>{ticketFilter=e.target.value;updateTicketList();});bindComposer();}
